int comedi_ioctl_devinfo(struct comedi_device *dev, struct comedi_devinfo __user *arg, struct file *file) {
    struct comedi_devinfo info;

    memset(&info, 0, sizeof(info));
    info.version_code = dev->version_code;
    info.n_subdevs = dev->n_subdevs;
    strncpy(info.driver_name, dev->driver->driver_name, sizeof(info.driver_name));
    strncpy(info.board_name, dev->board_name, sizeof(info.board_name));

    info.read_subdev = dev->read_subdev;
    info.write_subdev = dev->write_subdev;

    if (copy_to_user(arg, &info, sizeof(info))) {
        return -EFAULT;
    }

    return 0;
}
